<section class="wa-panel" data-wa-status-root aria-label="诡异药剂师死界状态栏">
  <style>
    .wa-panel {
      --wa-night: #070b12;
      --wa-ink: #0d1420;
      --wa-card: rgba(16, 28, 41, .88);
      --wa-line: #29445f;
      --wa-blue: #5bc5ff;
      --wa-blue-soft: #9bdcff;
      --wa-soul: #76f0d2;
      --wa-text: #e8f2f7;
      --wa-muted: #9cafbb;
      --wa-alert: #ff7185;
      box-sizing: border-box;
      width: 100%;
      margin: .8rem 0;
      color: var(--wa-text);
      font: 14px/1.55 ui-sans-serif, system-ui, "Microsoft YaHei", sans-serif;
    }
    .wa-panel * { box-sizing: border-box; }
