      width: .72rem;
      height: .95rem;
      border-radius: 52% 48% 56% 44%;
      background: var(--wa-soul);
      box-shadow: 0 0 9px rgba(118, 240, 210, .8), 0 0 22px rgba(91, 197, 255, .38);
